class CircularBuffer:
    def __init__(self, capacity):
        if type(capacity) is not int or capacity < 1:
            raise ValueError("Capacity must be positive")
        self._slots = [None] * capacity
        self._start = 0
        self._size = 0

    @property
    def capacity(self):
        return len(self._slots)

    @property
    def is_full(self):
        return self._size == len(self._slots)

    @property
    def is_empty(self):
        return self._size == 0

    def __len__(self):
        return self._size

    def push(self, item):
        capacity = len(self._slots)
        dropped = None
        if self._size == capacity:
            dropped = self._slots[self._start]
            self._slots[self._start] = item
            self._start = (self._start + 1) % capacity
        else:
            self._slots[(self._start + self._size) % capacity] = item
            self._size += 1
        return dropped

    def peek(self):
        if self._size == 0:
            raise ValueError("Buffer is empty")
        return self._slots[self._start]

    def pop(self):
        item = self.peek()
        self._slots[self._start] = None
        self._start = (self._start + 1) % len(self._slots)
        self._size -= 1
        return item

    def to_list(self):
        capacity = len(self._slots)
        return [self._slots[(self._start + offset) % capacity] for offset in range(self._size)]

    def __iter__(self):
        return iter(self.to_list())

    def latest(self, n):
        if n < 0:
            raise ValueError("Count cannot be negative")
        return list(reversed(self.to_list()))[:n]

    def clear(self):
        self._slots = [None] * len(self._slots)
        self._start = 0
        self._size = 0
